    anWeights[8] = 0x14;
    anWeights[9] = 0x1e;
    anWeights[10] = 0x96;
    anWeights[0xd] = 0x46;
    anWeights[0xe] = 0x28;
    anWeights[0xf] = 0;
    if (!pGame->nDifficulty) {
      nBaseWeight = 0x4b;
      anWeights[0xd] = 0x2d;
    }

