    anWeights[3] = 5;
    anWeights[4] = 5;
    anWeights[6] = 5;
    anWeights[0] = 0;
    int nBaseWeight;
    nBaseWeight = 100;
    anWeights[5] = 0;
    anWeights[7] = 0;
    anWeights[8] = 0x28;
    anWeights[9] = 0x28;
    anWeights[10] = 0;
    anWeights[0xb] = 0x46;
    anWeights[0xc] = 0x50;
    anWeights[0xd] = 0x3c;
    anWeights[0xe] = 0x14;
