    int32_t nDistToAnchorPt;
    D2RoomStrc* pRoom;
    uint16_t nCollisionHi;
    uint32_t nFoundGUID;
    D2UnitStrc* pFoundUnit;
    eD2LevelId eLevelId;
    uint32_t nDistToAnchor;
    int32_t eCollisionFlag;
