      pRoom = D2Common::Units::UNITS_GetRoom(pUnit);
      nAction = D2Common::Collision::CheckCollision_BlockPlayer_Type(pRoom, nDistToAnchorPt, nAction, nCollisionWidth, eCollisionFlag);
